def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    for r1 in range(h):
      for r2 in range(r1+2,h):
       for c1 in range(w):
        for c2 in range(c1+2,w):
         color=grid[r1][c1]
         if color==bg: continue
         if not (all(grid[r1][c]==color and grid[r2][c]==color for c in range(c1,c2+1)) and all(grid[r][c1]==color and grid[r][c2]==color for r in range(r1,r2+1))): continue
         vals={grid[r][c] for r in range(r1+1,r2) for c in range(c1+1,c2)}
         if len(vals)==1 and bg in vals:
          fill=2 if (r2-r1-1)%2==0 and (c2-c1-1)%2==0 else 7
          for r in range(r1+1,r2):
           for c in range(c1+1,c2): out[r][c]=fill
    return out

